function demoMain(idx,label){
  var pats=["\\d+","[a-z]+@[a-z]+","^#[0-9a-f]{6}$"];
  var p=pats[idx%pats.length];
  var tests=["abc123","user@host","#ff00aa"];var t=tests[idx%tests.length];
  return "["+label+"] /"+p+"/ vs '"+t+"' => "+(new RegExp(p).test(t)?"MATCH":"NO MATCH");
}

